groups.template:
@if(ecomStore.userInfo().roles.indexOf("OneCPQ Admin") != -1){
    @if(bundleGroup(); as bg){
                @if(toggleable()){    
                <div class="pt-2">
                    <p-panel class="pt-2" [collapsed]="collapsed()" [toggleable]="toggleable()" collapseIcon="pi pi-angle-left"
                        expandIcon="pi pi-angle-down">
                        <ng-template #header>
                            <div class="flex align-items-center gap-2">
                                <span class="font-bold">
                                    {{bg.label}}
                                </span>
                            </div>
                        </ng-template>
                        @if(toggleable()){
                        <ng-template #icons>
                            <button
                                class="p-0 p-ripple p-button p-component p-button-icon-only p-button-secondary p-button-rounded p-button-text p-panel-header-icon p-panel-toggler p-link"
                                (click)="setExpanded()">
                                <span [class]="'pi pi-angle-double-'+(collapsed() ? 'left':'down')"></span>
                            </button>
                        </ng-template>
                        }
                        <ng-container *ngTemplateOutlet="table"></ng-container>
                    </p-panel>
                </div>
            }
            @else {
                <ng-container *ngTemplateOutlet="table"></ng-container>
            }
            <ng-template #table>
    @if(bundleGroup(); as bg){
    @if(cartItemFeatureModels(); as cifs){
    <p-table size="small" styleClass="text-base " paginatorDropdownAppendTo="body"
        [paginator]="cifs.length >5?true:false" [rows]="10" [rowsPerPageOptions]="[5,10,20,50,75,100]" #dt
        responsiveLayout="stack" [value]="cifs">

        <ng-template #header>
            <tr>
                @for(property of bg.properties; track property){
                @let md = _.get(AppConst.bundleGroupColumns,property);
                <th
                    [class]="(md.type === 'number' ||md.type === 'currency' || md.type === 'percentage') ? 'text-right':''">
                    {{_.get(AppConst.bundleGroupColumns,property)?.label}}</th>
                }
            </tr>
        </ng-template>
        <ng-template #body let-item let-rowIndex="rowIndex">
            <tr class="bundleGroupTable" (click)="navigate(item)">
                @for(property of bg.properties; track property){

                @let md = _.get(AppConst.bundleGroupColumns,property);
                @if(md?.editable && editable()) {
                <td [class]="(md.type === 'number' ||md.type === 'currency' || md.type === 'percentage') ? 'text-right':''"
                    [pEditableColumn]="property" [pEditableColumnField]="property">
                    <span class="p-column-title">{{md.label}}</span>
                    @if(property === 'unitPrice'){

                    @let ftip = this.bundleGroupInterface()?.getPriceListDetail(item.featureTypeItem.id,'One Time');


                    @if(ftip?.isMatrix){
                    <span>

                        <p-button (click)="handleToggleMatrix(item.featureTypeItem,$event)" title="Matrix Detail"
                            styleClass="btb-rotate-45" icon="pi pi-thumbtack" [rounded]="true" [text]="true" />
                        <btb-shared-matrix-price-detail [cartItemFeature]="item"
                            [headerTitle]="(ftip?.matrixType ?? '') +' pricing - '+item.featureTypeItem.value"
                            [items]="ftip?.entries" [displayModal]="toggleViewModel()[item.featureTypeItem.id]">
                        </btb-shared-matrix-price-detail>
                    </span>
                    }
                    }
                    <p-cellEditor class="align-content-end">
                        <ng-template pTemplate="input">
                            @if(md.type === 'currency' || md.type === 'number'|| md.type === 'percentage') {
                            <input pInputText type="number" [(ngModel)]="item[property]">
                            }
                        </ng-template>
                        <ng-template pTemplate="output">
                            <span class="ref-link cursor-pointer">
                                {{getValue(item, property)}}
                            </span>
                        </ng-template>
                    </p-cellEditor>
                </td>    

                }
                @else {
                <td
                    [class]="(md.type === 'number' ||md.type === 'currency' || md.type === 'percentage') ? 'text-right':''">
                    <span class="p-column-title">{{md?.label}}</span>
                    {{getValue(item, property)}}
                </td>
                }
                }
            </tr>
        </ng-template>
        <ng-template #footer *ngIf="bg.showSummary">
            <tr>
                @for(property of bg.properties; track property){
                @let md = _.get(AppConst.bundleGroupColumns,property);
                <td
                    [class]="(md.type === 'number' ||md.type === 'currency' || md.type === 'percentage') ? 'text-right':''">
                    @if (md?.showSummary) {
                    {{_.get(summary(),property)}}
                    }

                </td>
                }
            </tr>
        </ng-template>
    </p-table>
    }
    }
</ng-template>
        }
}

actions.expr:
IIF(
CONTAINS(operator,'$[Quadrant]'),
1,
EVALUATE('
var staticPre = input.arg1;
var velocity = input.arg2;
var staticOut=0;
if(staticPre.indexOf("2Inch")!=-1) staticOut = 1;
if(staticPre.indexOf("4Inch")!=-1)  staticOut = 1.35;
if(staticPre.indexOf("6Inch")!=-1) staticOut = 1.45;

var valocityOut=0;
if(velocity.indexOf("1200")!=-1)  valocityOut = 1;
if(velocity.indexOf("2400")!=-1)  valocityOut = 1.25;
if(velocity.indexOf("3000")!=-1)  valocityOut = 1.35;
if(velocity.indexOf("4000")!=-1) valocityOut = 1.45;
return Math.max(staticOut,valocityOut);
',
SELECTEDVALUE(staticPressureClass),
SELECTEDVALUE(velocityRating)
)
)

EVALUATE('
var inpThickness = input.arg1;
var seleThickness = 0;
if(inpThickness != "") seleThickness = parseFloat(inpThickness.split(" ")[0]);
return Math.max(seleThickness,input.arg2);
',
IIF((COUNT(bladeSkinThickness)>0),SELECTEDVALUE(bladeSkinThickness),''),
CFLOAT(OBJECTATTRIBUTEF(unique,'min_blade_thickness'))
)
